-- 比赛 1070：修正厂牌归属、补录 6 款报名酒款并增加 1 款虚拟酒款。可重复执行。
SET NAMES utf8mb4;
SET time_zone = '+08:00';
START TRANSACTION;

-- 1. 将误并入嘉樂酿造的两位狐朋报名人拆分为独立厂牌。
SET @entry_hupeng_1 = (SELECT e.id FROM beer_entry e JOIN entry_scan_label l ON l.beer_entry_id = e.id WHERE e.competition_id = 1070 AND e.deleted_flag = 0 AND l.competition_id = 1070 AND l.short_code = '08918' LIMIT 1);
SET @entry_hupeng_2 = (SELECT e.id FROM beer_entry e JOIN entry_scan_label l ON l.beer_entry_id = e.id WHERE e.competition_id = 1070 AND e.deleted_flag = 0 AND l.competition_id = 1070 AND l.short_code = '13027' LIMIT 1);
SET @brewery_hupeng_1 = (SELECT brewery_id FROM portal_account WHERE phone = CONVERT(0x3138393838353135343134 USING utf8mb4) LIMIT 1);
SET @brewery_hupeng_1 = IF(@brewery_hupeng_1 = (SELECT brewery_id FROM portal_account WHERE phone = CONVERT(0x3133393738383536363633 USING utf8mb4) LIMIT 1), NULL, @brewery_hupeng_1);
INSERT INTO brewery (company_name, contact_name, phone, wechat) SELECT CONVERT(0xe78b90e69c8b USING utf8mb4), CONVERT(0xe890a7e4bf8ae993ad USING utf8mb4), CONVERT(0x3138393838353135343134 USING utf8mb4), CONVERT(0x3138393838353135343134 USING utf8mb4) WHERE @brewery_hupeng_1 IS NULL;
SET @brewery_hupeng_1 = (SELECT id FROM brewery WHERE company_name = CONVERT(0xe78b90e69c8b USING utf8mb4) AND phone = CONVERT(0x3138393838353135343134 USING utf8mb4) ORDER BY id DESC LIMIT 1);
UPDATE brewery SET company_name = CONVERT(0xe78b90e69c8b USING utf8mb4), contact_name = CONVERT(0xe890a7e4bf8ae993ad USING utf8mb4), phone = CONVERT(0x3138393838353135343134 USING utf8mb4), wechat = CONVERT(0x3138393838353135343134 USING utf8mb4) WHERE id = @brewery_hupeng_1;
UPDATE portal_account SET brewery_id = @brewery_hupeng_1, display_name = CONVERT(0xe78b90e69c8b USING utf8mb4), wechat = CONVERT(0x3138393838353135343134 USING utf8mb4) WHERE phone = CONVERT(0x3138393838353135343134 USING utf8mb4);
UPDATE beer_entry SET brewery_id = @brewery_hupeng_1 WHERE id = @entry_hupeng_1;
SET @brewery_hupeng_2 = (SELECT brewery_id FROM portal_account WHERE phone = CONVERT(0x3137373237313233373439 USING utf8mb4) LIMIT 1);
SET @brewery_hupeng_2 = IF(@brewery_hupeng_2 = (SELECT brewery_id FROM portal_account WHERE phone = CONVERT(0x3133393738383536363633 USING utf8mb4) LIMIT 1), NULL, @brewery_hupeng_2);
INSERT INTO brewery (company_name, contact_name, phone, wechat) SELECT CONVERT(0xe78b90e69c8b32 USING utf8mb4), CONVERT(0xe69d8ee59bbde99a86 USING utf8mb4), CONVERT(0x3137373237313233373439 USING utf8mb4), CONVERT(0x3137373237313233373439 USING utf8mb4) WHERE @brewery_hupeng_2 IS NULL;
SET @brewery_hupeng_2 = (SELECT id FROM brewery WHERE company_name = CONVERT(0xe78b90e69c8b32 USING utf8mb4) AND phone = CONVERT(0x3137373237313233373439 USING utf8mb4) ORDER BY id DESC LIMIT 1);
UPDATE brewery SET company_name = CONVERT(0xe78b90e69c8b32 USING utf8mb4), contact_name = CONVERT(0xe69d8ee59bbde99a86 USING utf8mb4), phone = CONVERT(0x3137373237313233373439 USING utf8mb4), wechat = CONVERT(0x3137373237313233373439 USING utf8mb4) WHERE id = @brewery_hupeng_2;
UPDATE portal_account SET brewery_id = @brewery_hupeng_2, display_name = CONVERT(0xe78b90e69c8b32 USING utf8mb4), wechat = CONVERT(0x3137373237313233373439 USING utf8mb4) WHERE phone = CONVERT(0x3137373237313233373439 USING utf8mb4);
UPDATE beer_entry SET brewery_id = @brewery_hupeng_2 WHERE id = @entry_hupeng_2;

-- 2. 狂歌与水门头仍共用一个账号和厂牌实体，仅修正展示名称。
SET @brewery_kuangge = (SELECT e.brewery_id FROM beer_entry e JOIN entry_scan_label l ON l.beer_entry_id = e.id WHERE e.competition_id = 1070 AND l.competition_id = 1070 AND l.short_code = '05127' LIMIT 1);
UPDATE brewery SET company_name = CONVERT(0xe78b82e6ad8c202f20e6b0b4e997a8e5a4b4 USING utf8mb4) WHERE id = @brewery_kuangge;
UPDATE portal_account SET display_name = CONVERT(0xe78b82e6ad8c202f20e6b0b4e997a8e5a4b4 USING utf8mb4) WHERE brewery_id = @brewery_kuangge;

