-- 4. 定位已有厂牌和账号。
SET @brewery_guoying = (SELECT b.id FROM brewery b LEFT JOIN portal_account a ON a.brewery_id = b.id WHERE b.company_name = CONVERT(0xe59c8be7879fe595a4e98592 USING utf8mb4) OR a.phone = CONVERT(0x3138303034343135383732 USING utf8mb4) ORDER BY b.id LIMIT 1);
SET @brewery_baolin = (SELECT b.id FROM brewery b LEFT JOIN portal_account a ON a.brewery_id = b.id WHERE b.company_name = CONVERT(0xe4bf9de99c96e7b2bee985bf USING utf8mb4) OR a.phone = CONVERT(0x3133393032343932383939 USING utf8mb4) ORDER BY b.id LIMIT 1);
INSERT INTO brewery (company_name, contact_name, phone, wechat) SELECT CONVERT(0xe4bf9de99c96e7b2bee985bf USING utf8mb4), CONVERT(0xe6b288e4bc9f USING utf8mb4), CONVERT(0x3133393032343932383939 USING utf8mb4), CONVERT(0x7669637669637377 USING utf8mb4) WHERE @brewery_baolin IS NULL;
SET @brewery_baolin = (SELECT b.id FROM brewery b LEFT JOIN portal_account a ON a.brewery_id = b.id WHERE b.company_name = CONVERT(0xe4bf9de99c96e7b2bee985bf USING utf8mb4) OR a.phone = CONVERT(0x3133393032343932383939 USING utf8mb4) ORDER BY b.id LIMIT 1);
UPDATE brewery SET company_name = CONVERT(0xe4bf9de99c96e7b2bee985bf USING utf8mb4), contact_name = CONVERT(0xe6b288e4bc9f USING utf8mb4), phone = CONVERT(0x3133393032343932383939 USING utf8mb4), wechat = CONVERT(0x7669637669637377 USING utf8mb4) WHERE id = @brewery_baolin;
INSERT INTO portal_account (phone, wechat, display_name, brewery_id, status) SELECT CONVERT(0x3133393032343932383939 USING utf8mb4), CONVERT(0x7669637669637377 USING utf8mb4), CONVERT(0xe4bf9de99c96e7b2bee985bf USING utf8mb4), @brewery_baolin, 1 WHERE NOT EXISTS (SELECT 1 FROM portal_account WHERE phone = CONVERT(0x3133393032343932383939 USING utf8mb4));
UPDATE portal_account SET brewery_id = @brewery_baolin, wechat = CONVERT(0x7669637669637377 USING utf8mb4), display_name = CONVERT(0xe4bf9de99c96e7b2bee985bf USING utf8mb4), status = 1 WHERE phone = CONVERT(0x3133393032343932383939 USING utf8mb4);
SET @brewery_virtual = (SELECT b.id FROM brewery b LEFT JOIN portal_account a ON a.brewery_id = b.id WHERE a.phone = CONVERT(0x3137353032313832353330 USING utf8mb4) ORDER BY b.id LIMIT 1);
INSERT INTO brewery (company_name, contact_name, phone, wechat) SELECT CONVERT(0xe5a4a9e5aeb8e79a84e98592e58e82 USING utf8mb4), CONVERT(0xe5be85e5ae8ce59684 USING utf8mb4), CONVERT(0x3137353032313832353330 USING utf8mb4), NULL WHERE @brewery_virtual IS NULL;
SET @brewery_virtual = (SELECT b.id FROM brewery b LEFT JOIN portal_account a ON a.brewery_id = b.id WHERE b.phone = CONVERT(0x3137353032313832353330 USING utf8mb4) OR a.phone = CONVERT(0x3137353032313832353330 USING utf8mb4) ORDER BY b.id LIMIT 1);
INSERT INTO portal_account (phone, wechat, display_name, brewery_id, status) SELECT CONVERT(0x3137353032313832353330 USING utf8mb4), NULL, CONVERT(0xe5a4a9e5aeb8e79a84e98592e58e82 USING utf8mb4), @brewery_virtual, 1 WHERE NOT EXISTS (SELECT 1 FROM portal_account WHERE phone = CONVERT(0x3137353032313832353330 USING utf8mb4));
UPDATE portal_account SET brewery_id = @brewery_virtual, status = 1 WHERE phone = CONVERT(0x3137353032313832353330 USING utf8mb4);

