-- 执行后立即显示本补丁涉及的酒款。
SELECT l.short_code, e.name, b.company_name, b.contact_name, e.style, e.abv, l.status FROM beer_entry e JOIN brewery b ON b.id = e.brewery_id JOIN entry_scan_label l ON l.beer_entry_id = e.id WHERE e.competition_id = 1070 AND e.deleted_flag = 0 AND l.short_code IN ('08918','13027','05127','32222','32223','12211','12212','12213','12214',CONVERT(0x3332373539 USING utf8mb4)) ORDER BY l.short_code;
